1	/**
2	 * turn-labels.ts — the two labels that say whose ball a node's turn is, moved together.
3	 *
4	 * `atomaton/in-progress` says work is in flight under the node: a run executing, or
5	 * a turn parked on agents working under it (#208). `atomaton/waiting-for-person`
6	 * says the turn came back and the machinery is waiting for a person (#223). The two
7	 * are complementary by construction, which is why one function moves both: a caller
8	 * that remembered to add one and forgot the other would leave a node wearing both
9	 * or neither, and neither state is readable.
10	 *
11	 * A closed node — an issue closed, a pull request merged or dropped — carries
12	 * NEITHER (#352). The turn is over, and a label naming who holds it names nobody:
13	 * a closed issue cannot be replied to through the machinery, so the waiting side
14	 * reads as a request nobody can act on, and the running side outlives the work it
15	 * describes. This takes back half of #223's rule — that label deliberately stayed
16	 * on a closed node as the filter of work that stopped there — because the filter
17	 * caught the person's eye as a live question on work that was over (#348, #335,
18	 * #338 on the pull-request side, #342 on the issue side); the thread tells that
19	 * story instead.
20	 *
21	 * The close is enforced here, at the one function every label writer calls, rather
22	 * than at each caller: a run that merges its own pull request and ends, a hand-off
23	 * refused because the target closed, the watch healing a run that died after its
24	 * node closed — all of them arrive here carrying a phase the node has already left.
25	 * The state is read, not assumed; the writers that run AFTER a close are exactly
26	 * the ones whose phase knowledge is stale. The readers that name `closed` directly
27	 * (the close-event strips and the runner's end-of-run strip) make the same read,
28	 * for a different half: the state names nothing new to them, but it names what the
29	 * node is wearing, and the removals take only what is on — so a strip that fires
30	 * on a node with neither label makes no write at all, and the repository's
31	 * unlabeled closes stay silent.
32	 *
33	 * Best effort throughout, like every label write: the thread is the turn's record
34	 * and the labels are its cache. Every failure is a warning naming what was lost.
35	 */
36	import { gh, ghRead } from "../../../adapters/github/gh.ts";
37	import { getLabel } from "../../../adapters/runner/config.ts";
38	import { readTargetState } from "../../../adapters/github/target-state.ts";
39	
40	export type TurnLabelPhase =
41	  /** A run took the turn: `in-progress` on, `waiting-for-person` off. */
42	  | "running"
43	  /** The turn came back to a person: `in-progress` off, `waiting-for-person` on. */
44	  | "with-person"
45	  /** The node is closed (#352): both come off, neither goes on. */
46	  | "closed";
47	
48	export function applyTurnLabels(phase: TurnLabelPhase, repo: string, number: string): void {
49	  const inProgress = getLabel("in_progress");
50	  const waitingForPerson = getLabel("waiting_for_person");
51	  const edit = (action: "--add-label" | "--remove-label", label: string) =>
52	    gh("issue", "edit", number, action, label, ...(repo ? ["--repo", repo] : []));
53	
54	  // Created if missing, so a renamed label or a fresh config still lands. `--repo`
55	  // travels with every call: a caller working in one checkout may be applying the
56	  // labels to another repository, and a label created in the wrong one makes the
57	  // `issue edit` fail as "label not found" (the #223 review's third point).
58	  const create = (label: string, color: string, description: string) =>
59	    gh("label", "create", label, "--force", "-c", color, "-d", description, ...(repo ? ["--repo", repo] : []));
60	
61	  // What the node is wearing, from the same read that answers whether it is still
62	  // open. A caller that could not read it removes unconditionally, the way every
63	  // caller did before #352: a failed read is not an answer, and the release still
64	  // has to take its guard down. The window between this read and the removal is
65	  // the same best-effort window every label write here has always had.
66	  const state = readTargetState(number, repo);
67	  const present = state.known ? new Set(state.labels ?? []) : undefined;
68	  const remove = (label: string) => {
69	    if (present !== undefined && !present.has(label)) return;
70	    const removed = edit("--remove-label", label);
71	    if (removed.code !== 0) console.error(`::warning::could not remove '${label}' from #${number}`);
72	  };
73	
74	  // A caller that arrived here after the node closed — a release following its own
75	  // merge, a refusal aimed at a closed target — has its phase bent to `closed`
76	  // (#352). A caller that could not read the state is not told the node is open:
77	  // it keeps the phase it brought, the pre-#352 behavior, rather than guessing.
78	  let effective = phase;
79	  if (phase !== "closed") {
80	    if (!state.known) {
81	      console.error(`::warning::could not read #${number}'s state (${state.why}); applying '${phase}' labels without the closed guard`);
82	    } else if (state.state !== "open") {
83	      console.error(`#${number} is closed; the turn labels come off and neither goes on (#352)`);
84	      effective = "closed";
85	    }
86	  }
87	
88	  if (effective === "closed") {
89	    remove(waitingForPerson);
90	    remove(inProgress);
91	    return;
92	  }
93	
94	  if (effective === "running") {
95	    create(inProgress, "0366d6", "Issue is being worked on by an Atomaton agent");
96	    const added = edit("--add-label", inProgress);
97	    if (added.code !== 0) console.error(`::warning::could not add '${inProgress}' to #${number}`);
98	    remove(waitingForPerson);
99	    return;
100	  }
101	
102	  create(waitingForPerson, "fbca04", "The turn is with a person on this issue or pull request");
103	  remove(inProgress);
104	  const added = edit("--add-label", waitingForPerson);
105	  if (added.code !== 0) console.error(`::warning::could not add '${waitingForPerson}' to #${number}`);
106	}

